import { defineComponent, markRaw } from 'vue';
import { Container, Point } from 'pixi.js';
import { eventEmitter } from '../../../services/event-emitter';

export default defineComponent({
    name: 'SelectionView',
    props: {
    },
    data() {
        return {
            currentElement: null as Container | null,
            visible: false,
            circleX: 0,
            circleY: 0,
            topLeft: { x: 0, y: 0 },
            topRight: { x: 0, y: 0 },
            bottomLeft: { x: 0, y: 0 },
            bottomRight: { x: 0, y: 0 },
            animationFrameId: null as number | null
        };
    },
    computed: {
        polygonPoints(): string {
            return `${this.topLeft.x},${this.topLeft.y} ${this.topRight.x},${this.topRight.y} ${this.bottomRight.x},${this.bottomRight.y} ${this.bottomLeft.x},${this.bottomLeft.y}`;
        }
    },
    mounted(): void {
        eventEmitter.on('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.onElementSelected, this);
        eventEmitter.addListener('DEBUG_INSPECTOR_SHOW_REQUESTED', (show) => {
            this.visible = show;
        });
        this.startAnimation();
    },
    beforeUnmount(): void {
        eventEmitter.off('DEBUG_INSPECTOR_ELEMENT_SELECTED', this.onElementSelected, this);
        this.stopAnimation();
    },
    methods: {
        onElementSelected(element: Container | null): void {
            this.currentElement = element ? markRaw(element) : null;
        },
        startAnimation(): void {
            const updatePosition = () => {
                if (this.currentElement && this.visible) {
                    const globalPos = this.currentElement.toGlobal(new Point(0, 0));
                    this.circleX = globalPos.x;
                    this.circleY = globalPos.y;

                    const bounds = this.currentElement.getBounds();
                    this.topLeft = { x: bounds.x, y: bounds.y };
                    this.topRight = { x: bounds.x + bounds.width, y: bounds.y };
                    this.bottomLeft = { x: bounds.x, y: bounds.y + bounds.height };
                    this.bottomRight = { x: bounds.x + bounds.width, y: bounds.y + bounds.height };
                }
                this.animationFrameId = requestAnimationFrame(updatePosition);
            };
            updatePosition();
        },
        stopAnimation(): void {
            if (this.animationFrameId !== null) {
                cancelAnimationFrame(this.animationFrameId);
                this.animationFrameId = null;
            }
        }
    }
});
